<script setup lang="ts">
import {onMounted,ref,watch} from 'vue';import {searchNotes,exportNotes} from '../api/study';import type{Note}from'../api/reader'
const notes=ref<Note[]>([]),query=ref(''),favorite=ref(false),documentId=ref<number>(),tagId=ref<number>(),loading=ref(false),status=ref('');let timer=0
const load=async()=>{loading.value=true;try{notes.value=await searchNotes({query:query.value||undefined,favorite:favorite.value||undefined,documentId:documentId.value,tagId:tagId.value})}finally{loading.value=false}}
watch([query,favorite,documentId,tagId],()=>{clearTimeout(timer);timer=window.setTimeout(load,250)});onMounted(load)
const download=async()=>{if(!documentId.value){status.value='请先输入资料编号';return}const {data}=await exportNotes(documentId.value);const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='notes.md';a.click();URL.revokeObjectURL(url);status.value='笔记已导出'}
</script>
<template><div class="page notes-page"><p class="eyebrow">NOTES</p><h1>全部笔记</h1><div class="study-toolbar"><label>搜索<input v-model="query" placeholder="按原文或笔记正文逐字搜索"></label><label>资料编号<input v-model.number="documentId" type="number"></label><label>标签编号<input v-model.number="tagId" type="number"></label><label><input v-model="favorite" type="checkbox">仅收藏</label><button class="button secondary" @click="download">导出 Markdown</button></div><p aria-live="polite">{{status}}</p><p v-if="loading">正在加载…</p><div v-else class="note-grid"><article v-for="note in notes" :key="note.id"><header><strong>资料 #{{note.documentId}}</strong><RouterLink :to="`/reader/${note.documentId}?page=${note.pageNumber||1}`">跳转来源</RouterLink></header><blockquote v-if="note.sourceText">{{note.sourceText}}</blockquote><pre>{{note.contentMarkdown}}</pre></article><p v-if="!notes.length">没有符合条件的笔记。</p></div></div></template>
